        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Do you know that conversation is one of the greatest pleasures in life? But it wants leisure.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "The tragedy of love is indifference.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "If a nation values anything more than freedom, it will lose its freedom; and the irony of it is that if it is comfort or money that it values more, it will lose that too.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "The Riviera isn't only a sunny place for shady people.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Now the world in general doesn't know what to make of originality; it is startled out of its comfortable habits of thought, and its first reaction is one of anger.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "It is unsafe to take your reader for more of a fool than he is.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Money is like a sixth sense - and you can't make use of the other five without it.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "What makes old age hard to bear is not the failing of one's faculties, mental and physical, but the burden of one's memories.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Dying is a very dull, dreary affair. And my advice to you is to have nothing whatever to do with it.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Money is the string with which a sardonic destiny directs the motions of its puppets.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "My own belief is that there is hardly anyone whose sexual life, if it were broadcast, would not fill the world at large with surprise and horror.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "A soul is a troublesome possession, and when man developed it he lost the Garden of Eden.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I hate people who play bridge as though they were at a funeral and knew their feet were getting wet.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "You know, there are two good things in life, freedom of thought and freedom of action.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Like all weak men he laid an exaggerated stress on not changing one's mind.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Art... is merely the refuge which the ingenious have invented, when they were supplied with food and women, to escape the tediousness of life.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Men seek but one thing in life — their pleasure.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "People ask you for criticism, but they only want praise.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "There is nothing so degrading as the constant anxiety about one's means of livelihood...Money is like a sixth sense without which you cannot make a complete use of the other five.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "It is not wealth one asks for, but just enough to preserve one's dignity, to work unhampered, to be generous, frank, and independent.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "It is cruel to discover one's mediocrity only when it is too late.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I daresay one profits more by the mistakes one makes off one's own bat than by doing the right thing on somebody's else advice.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Follow your inclinations with due regard to the policeman round the corner.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Of course it was cause and effect, but in the necessity with which follows the other lay all tragedy of life.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Life wouldn't be worth living if I worried over the future as well as the present. When things are at their worst I find something always happens.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "When I read a book I seem to read it with my eyes only, but now and then I come across a passage, perhaps only a phrase, which has a meaning for me, and it becomes part of me.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "It's no use crying over spilt milk, because all of the forces of the universe were bent on spilling it.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "But when all was said the important thing was to love rather than to be loved.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "There's always one who loves and one who lets himself be loved.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "It's asking a great deal that things should appeal to your reason as well as your sense of the aesthetic.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "The rain fell alike upon the just and upon the unjust, and for nothing was there a why and a wherefore.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "He had heard people speak contemptuously of money: he wondered if they had ever tried to do without it.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "It might be that to surrender to happiness was to accept defeat, but it was a defeat better than many victories.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "The modern clergyman has acquired in his study of the science which I believe is called exegesis an astonishing facility for explaining things away.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Impropriety is the soul of wit.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I reflected, while I chatted with the woman I had been asked to ‘take in’, that civilized man practises a strange ingenuity in wasting on tedious exercises the brief span of his life.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I did not then know the besetting sin of woman, the passion to discuss her private affairs with anyone who is willing to listen.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I had not yet learnt how contradictory is human nature; I did not know how much pose there is in the sincere, how much baseness in the noble, or how much goodness in the reprobate.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Conscience is the guardian in the individual of the rules which the community has evolved for its own preservation.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Whatever anguish she suffered she concealed. She saw shrewdly that the world is quickly bored by the recital of misfortune, and willingly avoids the sight of distress.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "She was making money. But she could not get over the idea that to earn her living was somewhat undignified, and she was inclined to remind you that she was a lady by birth.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "It is not true that suffering ennobles the character; happiness does that sometimes, but suffering, for the most part, makes men petty and vindictive.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I don't think of the past. The only thing that matters is the everlasting present.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Life isn't long enough for love and art.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "The poignancy which all beauty has.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "We must go through life so inconspicuously that Fate does not notice us.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "The writer is more concerned to know than to judge.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "A woman can forgive a man for the harm he does her, but she can never forgive him for the sacrifices he makes on her account.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Sometimes people carry to such perfection the mask they have assumed that in due course they actually become the person they seem.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Self-doubt, which is the artist's bitterest enemy.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "But who can fathom the subtleties of the human heart? Certainly not those who expect from it only decorous sentiments and normal emotions.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "He made one laugh sometimes by speaking the truth, but this is a form of humour which gains its force only by its unusualness; it would cease to amuse if it were commonly practised.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Perhaps some deep-rooted atavism urges the wanderer back to lands which his ancestors left in the dim beginnings of history.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Men are always the same. Fear makes them cruel.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Tahiti is very far away, and I knew that I should never see it again. A chapter of my life was closed, and I felt a little nearer to inevitable death.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "It's no good trying to keep up old friendships. It's painful for both sides. The fact is, one grows out of people, and the only thing is to face it.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Beauty is an ecstasy; it is as simple as hunger. There is really nothing to be said about it.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "...you know what the critics are. If you tell the truth they only say you're cynical and it does an author no good to get a reputation for cynicism.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "It's very hard to be a gentleman and a writer.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "...when you are young you take the kindness people show you as your right...", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "The writer of prose can only step aside when the poet passes...", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "There is no silence in the East.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Mandalay has its name; the falling cadence of the lovely word has gathered about itself the chiaroscuro of romance.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "The Chinese are the aristocracy of the East.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "They are like a face full of character that intrigues and excites you, but that on closer acquaintance you discover is merely the mask of a vulgar soul. Such is Tourane.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I would sooner read a time-table or a catalogue than nothing at all. ... They are much more entertaining than half the novels that are written.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "There is a sort of man who pays no attention to his good actions, but is tormented by his bad ones. This is the type that most often writes about himself.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I have not been afraid of excess: excess on occasion is exhilarating. It prevents moderation from acquiring the deadening effect of a habit.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "...the future will one day be the present and will seem as unimportant as the present does now.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "...we learn resignation not by our own suffering, but by the suffering of others.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "You are not angry with people when you laugh at them. Humour teaches tolerance, and the humorist, with a smile and perhaps a sigh, is more likely to shrug his shoulders than to condemn.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "The artist produces for the liberation of his soul. It is his nature to create as it is the nature of water to run down the hill.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Imagination grows by exercise, and contrary to common belief, is more powerful in the mature than in the young.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "... habits in writing as in life are only useful if they are broken as soon as they cease to be advantageous.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I'll give you my opinion of the human race in a nutshell... their heart's in the right place, but their head is a thoroughly inefficient organ.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I have been forced to conclude from this that we know our friends by their defects rather than by their merits.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "It is salutary to train oneself to be no more affected by censure than by praise...", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "The great critic ... must be a philosopher, for from philosophy he will learn serenity, impartiality, and the transitoriness of human things.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Tradition is a guide and not a jailer.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "There is no explanation for evil. It must be looked upon as a necessary part of the order of the universe. To ignore it is childish, to bewail it senseless.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Old age has its pleasures, which, though different, are not less than the pleasures of youth.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Old age is ready to undertake tasks that youth shirked because they would take too long.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Perfection is a trifle dull. It is not the least of life's ironies that this, which we all aim at, is better not quite achieved.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "We are not the same persons this year as last ; nor are those we love. It is a happy chance if we, changing, continue to love a changed person.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Every production of an artist should be the expression of an adventure of his soul.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I'm beginning to think it's very hard to know what to believe in this world.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "In point of fact, however, they were much more anxious to tell him about their doings than to listen to his.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Passion is destructive; if it does not destroy, it dies.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Nothing in the world is permanent, and we're foolish when we ask anything to last, but surely we're still more foolish not to take delight in it while we have it.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I thought I should be a fool to allow work to interfere with a delight in the passing moment that I might never enjoy again so fully.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "He was the kind of man with whom one would have hesitated to pass a lonely evening, but with whom one might cheerfully have looked forward to spending six months.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "It may be that if I lead the life I've planned for myself it may affect others; the effect may be no greater than the ripple caused by a stone thrown in a pond, but one ripple causes another.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Almost all the people who have had most effect on me I seem to have met by chance.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "American women expect to find in their husbands a perfection that English women only hope to find in their butlers.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Things don't get any easier by putting them off.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "He found himself now in the agreeable situation of being able to do what was best for others and at the same time what was convenient to himself.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Women are always glad to listen when you discourse upon love...", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Passion doesn't count the cost. ... Passion is destructive.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "In art honesty is not only the best but the only policy.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Religion is...a conspiracy of...priests to gain control over the people...", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "The sad Don Quixote of a worthless purpose.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "A god that can be understood is not a god.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Considering how foolishly people act and how pleasantly they prattle, perhaps it would be better for the world if they talked more and did less.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "The love that lasts longest is the love that is never returned.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Anyone can tell the truth, but only very few of us can make epigrams.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "The more intelligent a man is the more capable is he of suffering.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Men have an extraordinarily erroneous opinion of their position in nature; and the error is ineradicable.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Few misfortunes can befall a boy which bring worse consequences than to have a really affectionate mother.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "There is no object to life. To nature nothing matters but the continuation of the species.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "What mean and cruel things men can do for the love of God.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "If forty million people say a foolish thing it does not become a wise one, but the wise man is foolish to give them the lie.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "She plunged into a sea of platitudes, and with the powerful breast stroke of a channel swimmer made her confident way towards the white cliffs of the obvious.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Things were easier for the old novelists who saw people all of a piece. Speaking generally, their heroes were good through and through, their villains wholly bad.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "It was not till quite late in life that I discovered how easy it is to say: 'I don't know.'", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I made up my mind long ago that life was too short to do anything for myself that I could pay others to do for me.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Sentimentality is only sentiment that rubs you up the wrong way.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "At a dinner party one should eat wisely but not too well, and talk well but not too wisely.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "She had a pretty gift for quotation, which is a serviceable substitute for wit...", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Now it is a funny thing about life; if you refuse to accept anything but the best you very often get it...", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "Marriage is a very good thing, but I think it's a mistake to make a habit out of it.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "He had a bitter pain in his heart, for he knew that she was still a stranger to him and his hungry love was destined ever to remain unsatisfied.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I held my breath, for to me there is nothing more awe-inspiring than when a man discovers to you the nakedness of his soul.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I have always been convinced that if a woman once made up her mind to marry a man nothing but instant flight could save him.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "'I sometimes think,' said the Eternal, 'that the stars never shine more brightly than when reflected in the muddy waters of a wayside ditch.'", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "After all, a man marries to have a home, but also because he doesn't want to be bothered with sex and all that sort of thing.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "You can't learn too soon that the most useful thing about a principle is that it can always be sacrificed to expediency.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "You can do anything in this world if you are prepared to take the consequences.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "When you have loved as she has loved, you grow old beautifully.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "It was such a lovely day I thought it was a pity to get up.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "We have long passed the Victorian Era when asterisks were followed after a certain interval by a baby.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "You know that the Tasmanians, who never committed adultery, are now extinct.", Author = "W. Somerset Maugham" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._Somerset_Maugham", Text = "I was astonished to see him in Baghdad, for I had an appointment with him tonight in Samarra.", Author = "W. Somerset Maugham" },
